export const getPaymentWebhookUrl = () => {
  return `/api/payments/freekassa/webhook`;
};

export const paymentWebhook = async (
  webhookPayload: WebhookPayload,
  options?: RequestInit,
): Promise<PaymentStatus> => {
  const formUrlEncoded = new URLSearchParams();
  if (
    webhookPayload.MERCHANT_ID !== undefined &&
    webhookPayload.MERCHANT_ID !== null
  ) {
    formUrlEncoded.append(`MERCHANT_ID`, webhookPayload.MERCHANT_ID);
  }
  if (webhookPayload.AMOUNT !== undefined && webhookPayload.AMOUNT !== null) {
    formUrlEncoded.append(`AMOUNT`, webhookPayload.AMOUNT);
  }
  if (webhookPayload.intid !== undefined && webhookPayload.intid !== null) {
    formUrlEncoded.append(`intid`, webhookPayload.intid);
  }
  if (
    webhookPayload.MERCHANT_ORDER_ID !== undefined &&
    webhookPayload.MERCHANT_ORDER_ID !== null
  ) {
    formUrlEncoded.append(
      `MERCHANT_ORDER_ID`,
      webhookPayload.MERCHANT_ORDER_ID,
    );
  }
  if (webhookPayload.P_EMAIL !== undefined && webhookPayload.P_EMAIL !== null) {
    formUrlEncoded.append(`P_EMAIL`, webhookPayload.P_EMAIL);
  }
  if (webhookPayload.P_PHONE !== undefined && webhookPayload.P_PHONE !== null) {
    formUrlEncoded.append(`P_PHONE`, webhookPayload.P_PHONE);
  }
  if (webhookPayload.CUR_ID !== undefined && webhookPayload.CUR_ID !== null) {
    formUrlEncoded.append(`CUR_ID`, webhookPayload.CUR_ID);
  }
  if (webhookPayload.SIGN !== undefined && webhookPayload.SIGN !== null) {
    formUrlEncoded.append(`SIGN`, webhookPayload.SIGN);
  }
  if (
    webhookPayload.payer_account !== undefined &&
    webhookPayload.payer_account !== null
  ) {
    formUrlEncoded.append(`payer_account`, webhookPayload.payer_account);
  }
  if (
    webhookPayload.commission !== undefined &&
    webhookPayload.commission !== null
  ) {
    formUrlEncoded.append(`commission`, webhookPayload.commission);
  }

  return customFetch<PaymentStatus>(getPaymentWebhookUrl(), {
    ...options,
    method: "POST",
    headers: {
      "Content-Type": "application/x-www-form-urlencoded",
      ...options?.headers,
    },
    body: formUrlEncoded,
  });
};

